// cli-commands.json is generated by scripts/gen-cli-commands.py from the help
// text of the kicad-cli binary: every leaf subcommand with its positional
// arguments and options.  It is the validation schema for CLI actions.
//
//go:embed cli-commands.json
var cliCommandsJSON []byte

// CLIOption is one kicad-cli option.
type CLIOption struct {
	Long    string   `json:"long"`
	Aliases []string `json:"aliases,omitempty"`
	Help    string   `json:"help"`
	Value   bool     `json:"value"`
	Repeat  bool     `json:"repeat"`
	Default string   `json:"default,omitempty"`
}

// CLIPositional is one positional kicad-cli argument.
type CLIPositional struct {
	Name     string `json:"name"`
	Multiple bool   `json:"multiple"`
	Optional bool   `json:"optional"`
	Help     string `json:"help"`
}

// CLICommand is one kicad-cli leaf subcommand.
type CLICommand struct {
	Path        []string        `json:"path"`
	Usage       string          `json:"usage"`
	Summary     string          `json:"summary"`
	Positionals []CLIPositional `json:"positionals"`
	Options     []CLIOption     `json:"options"`
	// Action is the typed action serving this subcommand.
	Action string `json:"action"`
}

type cliDoc struct {
	GeneratedFrom string       `json:"generatedFrom"`
	Commands      []CLICommand `json:"commands"`
}

