var (
	cliOnce     sync.Once
	cliCommands []CLICommand
	cliFrom     string
	cliByAction map[string]CLICommand
)

func loadCLI() {
	cliOnce.Do(func() {
		var doc cliDoc
		_ = json.Unmarshal(cliCommandsJSON, &doc)
		cliFrom = doc.GeneratedFrom
		cliByAction = map[string]CLICommand{}
		for _, cmd := range doc.Commands {
			name, ok := cliPathAction[strings.Join(cmd.Path, " ")]
			if !ok {
				continue
			}
			cmd.Action = name
			cliCommands = append(cliCommands, cmd)
			cliByAction[name] = cmd
		}
	})
}

// CLICommands returns every kicad-cli subcommand exposed as a typed action.
func CLICommands() []CLICommand {
	loadCLI()
	return cliCommands
}

// CLIGeneratedFrom reports the kicad-cli version the schema was taken from.
func CLIGeneratedFrom() string {
	loadCLI()
	return cliFrom
}

// CLICommandFor returns the kicad-cli schema serving an action.
func CLICommandFor(action string) (CLICommand, bool) {
	loadCLI()
	cmd, ok := cliByAction[action]
	return cmd, ok
}

// PositionalKeys maps a command's positionals to payload keys: one input is
// "input", two are "fileA"/"fileB", a repeated one is "inputs", and named
// merge inputs keep their lower-case names.
func (c CLICommand) PositionalKeys() []string {
	switch {
	case len(c.Positionals) == 1 && c.Positionals[0].Multiple:
		return []string{"inputs"}
	case len(c.Positionals) == 1:
		return []string{"input"}
	case len(c.Positionals) == 2:
		return []string{"fileA", "fileB"}
	}
	keys := make([]string, 0, len(c.Positionals))
	for _, p := range c.Positionals {
		keys = append(keys, strings.ToLower(p.Name))
	}
	return keys
}

// OptionKey is the camelCase payload key for an option ("--common-layers" ->
// "commonLayers").
func OptionKey(long string) string {
	parts := strings.Split(strings.TrimLeft(long, "-"), "-")
	var b strings.Builder
	for i, part := range parts {
		if part == "" {
			continue
		}
		if i == 0 {
			b.WriteString(part)
			continue
		}
		r := []rune(part)
		r[0] = unicode.ToUpper(r[0])
		b.WriteString(string(r))
	}
	return b.String()
}

// NormalizeOptionKey folds case, dashes and underscores so "commonLayers",
// "common-layers", "--common-layers" and "common_layers" all match.
func NormalizeOptionKey(key string) string {
	key = strings.ToLower(strings.TrimLeft(key, "-"))
	return strings.NewReplacer("-", "", "_", "").Replace(key)
}

func cliGeneratedActions() []ActionSpec {
	var out []ActionSpec
	for _, cmd := range CLICommands() {
		if _, handwritten := handwrittenCLI[cmd.Action]; handwritten {
			continue
		}
		out = append(out, cliActionSpec(cmd))
	}
	return out
}

// handwrittenCLI actions are declared in coreActions with custom handlers; the
// generated schema only adds option validation to them.
var handwrittenCLI = map[string]bool{
	"system.version": true, "board.drc.run": true, "board.render": true, "board.diff": true,
	"board.export.gerbers": true, "board.export.drill": true, "board.export.position": true,
	"board.export.step": true, "board.export.svg": true, "board.export.pdf": true,
	"board.export.png": true, "board.export.ipc2581": true, "board.export.odb": true,
	"schematic.diff": true, "schematic.erc.run": true, "schematic.export.netlist": true,
	"schematic.export.bom": true, "schematic.export.pdf": true, "schematic.export.svg": true,
	"schematic.export.pythonbom": true,
}

func cliActionSpec(cmd CLICommand) ActionSpec {
	domain := Domain(strings.SplitN(cmd.Action, ".", 2)[0])
	inputs := []string{}
	for i, key := range cmd.PositionalKeys() {
		desc := key
		if i < len(cmd.Positionals) && cmd.Positionals[i].Help != "" {
			desc += " (" + cmd.Positionals[i].Help + ")"
		}
		inputs = append(inputs, desc)
	}
	for _, opt := range cmd.Options {
		key := OptionKey(opt.Long)
		if key == "output" {
			key = "output (or outputDir)"
		}
		if opt.Repeat {
			key += "[]"
		}
		if !opt.Value {
			key += " (bool)"
		}
		help := opt.Help
		if len(help) > 90 {
			help = help[:87] + "..."
		}
		inputs = append(inputs, key+" optional — "+help)
	}
	inputs = append(inputs, "timeoutMs optional")

	return ActionSpec{
		Name: cmd.Action, Domain: domain, Backend: BackendCLI, Mutates: cliMutating[cmd.Action],
		Description: cmd.Summary + " (kicad-cli " + strings.Join(cmd.Path, " ") + "; options are validated against its help).",
		Inputs:      inputs, Outputs: []string{"exitCode", "stdout", "stderr", "artifacts"},
		Keywords:    cliKeywords[cmd.Action], CLI: cmd.Path,
	}
}

// attachCLIPaths records the kicad-cli path on hand-written CLI actions.
func attachCLIPaths(actions []ActionSpec) {
	for i := range actions {
		if cmd, ok := CLICommandFor(actions[i].Name); ok && actions[i].Backend == BackendCLI {
			actions[i].CLI = cmd.Path
		}
	}
}

// CLICommandByPath returns the schema for a kicad-cli subcommand path.
func CLICommandByPath(path []string) (CLICommand, bool) {
	loadCLI()
	want := strings.Join(path, " ")
	for _, cmd := range cliCommands {
		if strings.Join(cmd.Path, " ") == want {
			return cmd, true
		}
	}
	return CLICommand{}, false
}
